from typing import List, Tuple, Union
from .message_handling import (SMessageHeader,
                               RequestMessage, ResponseMessage, Query, BasicQueryManager,
                               register_message, u32)
from .sack_reflection_interface import get_dsp_mode_description

from ..commons import DSP_RESOURCES


@register_message
class BrowserDspModeReq(RequestMessage):
    id = 0x1e21
    _fields_ = [
        ('header', SMessageHeader),
        ('spare', u32)
    ]


@register_message
class BrowserDspModeResp(ResponseMessage):
    id = 0x1e22
    _fields_ = [
        ('header', SMessageHeader),
        ('dspMode', u32)
    ]


class BrowserDspModeQuery(Query):
    def __init__(self, req, resp):
        super(BrowserDspModeQuery, self).__init__(req, resp)

        self.mode = None  # type: int
        self.mode_description = None  # type: str

    def _handle_response(self):
        mode = int(self.resp_msg.dspMode)
        self.mode = mode
        self.mode_description = get_dsp_mode_description(mode)


class DspModeInterface(object):
    def __init__(self, connection):
        self.connection = connection

    def get_dsp_mode(self, board, cpu, humanize, timeout=0.5):
        # type: (int, int, bool, float) -> (int, int, Union[int, str])
        query = BrowserDspModeQuery(BrowserDspModeReq(board, cpu), BrowserDspModeResp())
        qm = BasicQueryManager(query, self.connection)
        qm.send_request_and_wait_for_response(timeout)

        mode = query.mode_description if humanize else query.mode

        return (query.resp_msg.header.sender.board,
                query.resp_msg.header.sender.cpu,
                mode)

    def get_dsp_mode_for_board(self, board, humanize):
        # type: (int, bool) -> List[Tuple[Union[int, str], Union[int, str], Union[int, str]]]
        managers = []
        modes = []

        for cpu in DSP_RESOURCES.get_cpu_ids_for_board(board):
            query = BrowserDspModeQuery(BrowserDspModeReq(board, cpu), BrowserDspModeResp())
            qm = BasicQueryManager(query, self.connection)
            managers.append(qm)

        for qm in managers:
            qm.send_request_and_wait_for_response(timeout=0.2)
            board = qm.query.resp_msg.header.sender.board
            cpu = qm.query.resp_msg.header.sender.cpu
            mode = qm.query.mode

            if humanize:
                board = '0x{:x}'.format(board)
                cpu = '0x{:x}'.format(cpu)
                mode = qm.query.mode_description
            if mode:
                modes.append((board, cpu, mode))

        return modes
